{v:'VER',what:'the HUD spec: while the DEMO controls card is up (the spawn shield and 4 s after) the feed waits and draws nothing, then its lines appear when the card fades',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame||typeof arcadeCardOn!=='function') return 'SKIP: no raid or DEMO card here';
   if(typeof feedDraw!=='function'||typeof FEEDBOX==='undefined') return 'SKIP: no feed here';
   var bad=[], g, p, i, wasA, shT;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     p=g.player; g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={}; wasA=g.arcade; shT=p.arcShT;
     for(i=0;i<4;i++) say('CARD SHARE LINE '+i,'info');
     g.arcade=1; p.arcSh=1;
     for(i=0;i<3;i++) __frame(0.016);
     if(!(arcadeCardOn()>0)) return 'SKIP: the controls card is not up in this staging';
     if(FEEDBOX.rows.length) bad.push('the feed draws '+FEEDBOX.rows.length+' lines while the controls card is up');
     p.arcSh=0; p.arcShT=(g.t||0)-10;
     for(i=0;i<3;i++) __frame(0.016);
     if(arcadeCardOn()>0) bad.push('the card is still up 10 s after the shield');
     if(FEEDBOX.rows.length<4) bad.push('the feed has '+FEEDBOX.rows.length+' lines after the card faded, not its 4');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var g2=__state(); if(g2&&!g2.over){ g2.arcade=wasA; g2.player.arcSh=0; g2.player.arcShT=shT; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
